<?php function reportBars(array $rows): string { $max=max(1,...array_map(fn($r)=>(int)$r['total'],$rows));ob_start();foreach($rows as $r){$w=max(3,((int)$r['total']/$max)*100);echo '<div class="report-bar"><span>'.e(ucwords(str_replace('_',' ',$r['label']))).'</span><div><i style="--bar:'.$w.'%"></i></div><b>'.e($r['total']).'</b></div>';}return ob_get_clean();} ?>
<div class="page-heading admin-heading"><div><span class="eyebrow">Operational intelligence</span><h1>Admissions reports</h1><p>Live funnel, applicant profile, geography and team workload.</p></div><div class="heading-actions"><button class="button button-outline" onclick="window.print()">▣ Print / PDF</button><a class="button button-primary" href="<?= url('admin/applications/export') ?>">↓ Export source data</a></div></div><div class="report-notice"><span>i</span><p>Reports reflect the current database and active filters. Small category groups may require privacy suppression before external sharing.</p></div><div class="report-grid"><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Funnel</span><h2>Applications by status</h2></div></div><?= reportBars($status) ?></section><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Reservation view</span><h2>Applicant category</h2></div></div><?= reportBars($category) ?></section><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Profile</span><h2>Gender distribution</h2></div></div><?= reportBars($gender) ?></section><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Geography</span><h2>Top applicant states</h2></div></div><?= reportBars($geography) ?></section><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Team capacity</span><h2>Reviewer workload</h2></div></div><?= $reviewers?reportBars($reviewers):'<div class="empty-inline">No assigned applications yet.</div>' ?></section><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Recent pace</span><h2>Daily submissions</h2></div></div><?= $daily?reportBars(array_reverse($daily)):'<div class="empty-inline">No submitted applications yet.</div>' ?></section></div>
